        if len(vals) == 1:
            color = grid[0][c]
            if color != background:
                separators.append(("v", c, color))
    if not separators:
        return out
    orientation, line, sep_color = separators[0]
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != background and grid[r][c] != sep_color]
    if not points:
        return out

    if orientation == "v":
        left_side = max(c for r, c, color in points) < line
        right_side = min(c for r, c, color in points) > line
        if not (left_side or right_side):
            return out
        if left_side:
            shift = line - 1 - max(c for r, c, color in points)
            direction = 1
        else:
            shift = line + 1 - min(c for r, c, color in points)
            direction = -1

        # Ignore a single one-cell cap on an otherwise solid rectangle.
        # It marks the edge while the rectangular body is shifted.
        if direction == 1:
            rs = [r for r, c, color in points]; cs = [c for r, c, color in points]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
